package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99
var WsNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99
var WsCount int64 = 0 // PIC 9(3)
var WsIncEd string // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var TaxRecData TaxRec
var taxLines []string
var taxIdx int

func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	scaled := v.Shift(scale).Truncate(0)
	neg := scaled.IsNegative()
	absScaled := scaled.Abs()
	powTotal := decimal.NewFromInt(1).Shift(int32(intDigits) + scale)
	modAbs := absScaled.Mod(powTotal)
	if neg {
		modAbs = modAbs.Neg()
	}
	return modAbs.Shift(-scale)
}

func fitInt(v int64, digits int) int64 {
	pow := int64(1)
	for i := 0; i < digits; i++ {
		pow *= 10
	}
	if v >= 0 {
		return v % pow
	}
	return -((-v) % pow)
}

func formatEdited(v decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPat, fracPat string
	if dotIdx >= 0 {
		intPat = picture[:dotIdx]
		fracPat = picture[dotIdx+1:]
	} else {
		intPat = picture
		fracPat = ""
	}
	fracDigits := len(fracPat)
	intSlots := 0
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	vt := v.Truncate(int32(fracDigits))
	a := vt.Abs()
	intPart := a.Truncate(0)
	fracPart := a.Sub(intPart).Shift(int32(fracDigits)).Truncate(0)

	intStrRaw := intPart.String()
	if idx := strings.Index(intStrRaw, "."); idx >= 0 {
		intStrRaw = intStrRaw[:idx]
	}
	intStrRaw = strings.TrimPrefix(intStrRaw, "-")
	intStrRaw = strings.TrimPrefix(intStrRaw, "+")
	if intStrRaw == "" {
		intStrRaw = "0"
	}
	var intDigits string
	if len(intStrRaw) > intSlots {
		intDigits = intStrRaw[len(intStrRaw)-intSlots:]
	} else if len(intStrRaw) < intSlots {
		intDigits = strings.Repeat("0", intSlots-len(intStrRaw)) + intStrRaw
	} else {
		intDigits = intStrRaw
	}

	fracStrRaw := fracPart.String()
	if idx := strings.Index(fracStrRaw, "."); idx >= 0 {
		fracStrRaw = fracStrRaw[:idx]
	}
	fracStrRaw = strings.TrimPrefix(fracStrRaw, "-")
	fracStrRaw = strings.TrimPrefix(fracStrRaw, "+")
	if fracStrRaw == "" {
		fracStrRaw = "0"
	}
	var fracDigitsStr string
	if len(fracStrRaw) > fracDigits && fracDigits > 0 {
		fracDigitsStr = fracStrRaw[len(fracStrRaw)-fracDigits:]
	} else if len(fracStrRaw) < fracDigits {
		fracDigitsStr = strings.Repeat("0", fracDigits-len(fracStrRaw)) + fracStrRaw
	} else {
		fracDigitsStr = fracStrRaw
	}
	if fracDigits == 0 {
		fracDigitsStr = ""
	}

	digitIdx := 0
	suppressed := true
	outInt := make([]byte, len(intPat))
	for i := 0; i < len(intPat); i++ {
		ch := intPat[i]
		if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' {
			d := intDigits[digitIdx]
			digitIdx++
			if suppressed && d == '0' {
				outInt[i] = ' '
			} else {
				outInt[i] = d
				suppressed = false
			}
		} else if ch == '9' {
			d := intDigits[digitIdx]
			digitIdx++
			outInt[i] = d
			suppressed = false
		} else {
			outInt[i] = ch
		}
	}
	var sb strings.Builder
	sb.Write(outInt)
	if dotIdx >= 0 {
		sb.WriteByte('.')
		fracIdx := 0
		for i := 0; i < len(fracPat); i++ {
			ch := fracPat[i]
			if ch == '9' || ch == 'Z' {
				d := fracDigitsStr[fracIdx]
				fracIdx++
				sb.WriteByte(d)
			} else {
				sb.WriteByte(ch)
			}
		}
	}
	return sb.String()
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		taxLines = nil
	} else {
		s := string(data)
		parts := strings.Split(s, "\n")
		if strings.HasSuffix(s, "\n") {
			parts = parts[:len(parts)-1]
		}
		taxLines = make([]string, len(parts))
		for i, p := range parts {
			if strings.HasSuffix(p, "\r") {
				p = p[:len(p)-1]
			}
			taxLines[i] = p
		}
	}
	taxIdx = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Fprint(os.Stdout, "TAXPAYERS: "+countStr+" TOTAL TAX: "+WsTotalEd+"\n")
}

func ReadPara() {
	if taxIdx >= len(taxLines) {
		WsEofFlag = "Y"
		return
	}
	line := taxLines[taxIdx]
	taxIdx++
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	idPart := line[0:5]
	incPart := line[5:13]
	TaxRecData.TrId = idPart
	s := strings.TrimSpace(incPart)
	var n int64 = 0
	if s != "" {
		v, err := strconv.ParseInt(s, 10, 64)
		if err != nil {
			digits := ""
			neg := false
			for _, ch := range s {
				if ch >= '0' && ch <= '9' {
					digits += string(ch)
				} else if ch == '-' {
					neg = true
				}
			}
			if digits == "" {
				n = 0
			} else {
				v2, err2 := strconv.ParseInt(digits, 10, 64)
				if err2 != nil {
					n = 0
				} else {
					n = v2
					if neg {
						n = -n
					}
				}
			}
		} else {
			n = v
		}
	}
	TaxRecData.TrIncome = decimal.New(n, -2)
}

func ProcessPara() {
	c10000 := decimal.NewFromInt(10000)
	c40000 := decimal.NewFromInt(40000)
	if TaxRecData.TrIncome.Cmp(c10000) <= 0 {
		rate := decimal.New(10, -2)
		tmp := TaxRecData.TrIncome.Mul(rate)
		rounded := tmp.Round(2)
		WsTax = fitDecimal(rounded, 7, 2)
	} else {
		if TaxRecData.TrIncome.Cmp(c40000) <= 0 {
			rate := decimal.New(20, -2)
			c1000 := decimal.NewFromInt(1000)
			tmp := TaxRecData.TrIncome.Sub(c10000).Mul(rate).Add(c1000)
			rounded := tmp.Round(2)
			WsTax = fitDecimal(rounded, 7, 2)
		} else {
			rate := decimal.New(30, -2)
			c7000 := decimal.NewFromInt(7000)
			tmp := TaxRecData.TrIncome.Sub(c40000).Mul(rate).Add(c7000)
			rounded := tmp.Round(2)
			WsTax = fitDecimal(rounded, 7, 2)
		}
	}
	tmpNet := TaxRecData.TrIncome.Sub(WsTax)
	truncNet := tmpNet.Truncate(2)
	WsNet = fitDecimal(truncNet, 7, 2)
	tmpTot := WsTotalTax.Add(WsTax)
	truncTot := tmpTot.Truncate(2)
	WsTotalTax = fitDecimal(truncTot, 9, 2)
	WsCount = fitInt(WsCount+1, 3)
	WsIncEd = formatEdited(TaxRecData.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	idOut := TaxRecData.TrId
	if len(idOut) < 5 {
		idOut = idOut + strings.Repeat(" ", 5-len(idOut))
	} else if len(idOut) > 5 {
		idOut = idOut[:5]
	}
	fmt.Fprint(os.Stdout, idOut+" "+WsIncEd+" "+WsTaxEd+" "+WsNetEd+"\n")
	ReadPara()
}

func main() {
	MainPara()
}
